import os
from typing import Iterable, Iterator, Optional

from azure.cognitiveservices.speech import (
    AudioConfig,
    CancellationDetails,
    CancellationReason,
    SpeechConfig,
    SpeechRecognizer,
    ResultReason,
)


class StreamingSpeechToText:
    def __init__(
        self,
        language: str = "en-US",
        enable_punctuation: bool = True,
        subscription_key: Optional[str] = None,
        region: Optional[str] = None,
    ):
        self.subscription_key = subscription_key or os.getenv("AZURE_SPEECH_KEY")
        self.region = region or os.getenv("AZURE_SPEECH_REGION")
        if not self.subscription_key:
            raise ValueError("Missing Azure Speech key. Set AZURE_SPEECH_KEY or pass subscription_key.")
        if not self.region:
            raise ValueError("Missing Azure Speech region. Set AZURE_SPEECH_REGION or pass region.")

        self.speech_config = SpeechConfig(subscription=self.subscription_key, region=self.region)
        self.speech_config.speech_recognition_language = language
        self.speech_config.set_property(
            property_id=SpeechConfig.PropertyId.SpeechServiceResponse_PostProcessingOption,
            value="TrueText" if enable_punctuation else "FalseText",
        )

    def recognize_from_microphone(self) -> Iterator[str]:
        audio_config = AudioConfig(use_default_microphone=True)
        recognizer = SpeechRecognizer(speech_config=self.speech_config, audio_config=audio_config)
        return self._stream_recognizer(recognizer)

    def recognize_from_wav_file(self, wav_path: str) -> Iterator[str]:
        audio_config = AudioConfig(filename=wav_path)
        recognizer = SpeechRecognizer(speech_config=self.speech_config, audio_config=audio_config)
        return self._stream_recognizer(recognizer)

    def _stream_recognizer(self, recognizer: SpeechRecognizer) -> Iterator[str]:
        done = {"flag": False}

        def stop_cb(evt):
            done["flag"] = True

        results = []

        def recognized_cb(evt):
            if evt.result.reason == ResultReason.RecognizedSpeech and evt.result.text:
                results.append(evt.result.text)

        def canceled_cb(evt):
            details = CancellationDetails(evt.result)
            if details.reason == CancellationReason.Error:
                raise RuntimeError(f"Speech recognition canceled: {details.error_details}")
            done["flag"] = True

        recognizer.recognized.connect(recognized_cb)
        recognizer.canceled.connect(canceled_cb)
        recognizer.session_stopped.connect(stop_cb)

        recognizer.start_continuous_recognition()

        try:
            while not done["flag"]:
                if results:
                    yield results.pop(0)
        finally:
            recognizer.stop_continuous_recognition()
